/* eslint-disable react-hooks/set-state-in-effect */
import { useState, useRef, useEffect } from "react";
import { useNavigate } from "react-router-dom";

import {
  Heart,
  MapPin,
  MessageCircle,
  Repeat2,
  Send,
  MoreHorizontal,
  BadgeCheck,
  Copy,
  Flag,
  UserMinus,
  Share2,
  ExternalLink,
  Trash2,
  HandHeart,
  Ban,
  Bookmark,
  AlertTriangle,
} from "lucide-react";
import { motion } from "framer-motion";

import { useAuth } from "../../context/AuthContext";
import { useTheme } from "@/context/ThemeContext";
import { COMMUNITIES } from "@/constants/communities";
import { db } from "../../firebase/firebase";
import { doc, updateDoc, deleteDoc, increment, onSnapshot, runTransaction } from "firebase/firestore";
import { toast } from "sonner";
import type { FeedPost } from "./Feed";
import { useLiveProfile } from "@/hooks/useLiveProfile";
import { createNotification } from "@/services/notifications";
import {
  createIssueCommunityForPost,
  getUserSummary,
  joinIssueCommunity,
  listenCommunityByPost,
  listenCommunityMember,
} from "@/services/volunteering";
import type { CommunityMember, IssueCommunity } from "@/types/volunteering";
import { recordPostEngagement } from "@/services/engagementEvents";
import { formatDistance, locationLabel, normalizeLocation } from "@/services/location";

import CommentsSheet from "../comments/CommentsSheet";
import MediaGrid from "./MediaGrid";
import type { PostMediaItem } from "./MediaGrid";
import PostSendSheet from "./PostSendSheet";
import { listenToReHiveState, toggleReHive } from "@/services/rehives";
import { listenToSavedPostState, toggleSavePost } from "@/services/savedPosts";
import { blockIdFor, blockUser, unblockUser } from "@/services/blocks";
import { createReport } from "@/services/admin";
import type { TimestampLike } from "@/types/timestamp";

interface Props {
  post: FeedPost;
  onCommentClick?: (post: FeedPost) => void;
}

function timeAgo(timestamp?: TimestampLike | null) {
  if (!timestamp?.toDate) return "Now";

  const seconds = Math.floor(
    (Date.now() - timestamp.toDate().getTime()) / 1000
  );

  if (seconds < 60) return "Now";
  const minutes = Math.floor(seconds / 60);
  if (minutes < 60) return `${minutes}m`;
  const hours = Math.floor(minutes / 60);
  if (hours < 24) return `${hours}h`;
  const days = Math.floor(hours / 24);
  if (days < 7) return `${days}d`;
  const weeks = Math.floor(days / 7);
  if (weeks < 52) return `${weeks}w`;
  const years = Math.floor(days / 365);
  return `${years}y`;
}

export default function FeedCard({ post, onCommentClick }: Props) {
  const { user, profile: myProfile } = useAuth();
  const { reducedMotion } = useTheme();
  const navigate = useNavigate();
  // Live author profile: name/username/avatar/verification stay current even
  // though the post document stores a creation-time snapshot.
  const author = useLiveProfile(post.uid, post) as FeedPost;
  const [liked, setLiked] = useState(false);
  const [likesCount, setLikesCount] = useState(post.likes);
  const [reHived, setReHived] = useState(false);
  const [reHiveCount, setReHiveCount] = useState(post.reHives || 0);
  const [reHiving, setReHiving] = useState(false);
  const [saved, setSaved] = useState(false);
  const [saving, setSaving] = useState(false);
  const [blockState, setBlockState] = useState<"none" | "blocked-by-me" | "blocked-them">("none");
  const [blockBusy, setBlockBusy] = useState(false);
  const [commentsOpen, setCommentsOpen] = useState(false);
  const [sendSheetOpen, setSendSheetOpen] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);
  const [shareMenuOpen, setShareMenuOpen] = useState(false);
  const [copied, setCopied] = useState(false);
  const [liking, setLiking] = useState(false);
  const [community, setCommunity] = useState<IssueCommunity | null>(null);
  const [communityMember, setCommunityMember] = useState<CommunityMember | null>(null);
  const [volunteerBusy, setVolunteerBusy] = useState(false);
  const mediaItems: PostMediaItem[] =
    post.mediaItems?.length
      ? post.mediaItems
      : post.mediaUrls?.length
      ? post.mediaUrls.map((url) => ({ url, type: post.mediaType === "video" ? "video" : "image" }))
      : post.mediaUrl
      ? [{ url: post.mediaUrl, type: post.mediaType === "video" ? "video" : "image" }]
      : [];
  const postLocation = normalizeLocation(post.locationSnapshot);
  const readableLocation = locationLabel(postLocation, post.location);

  const menuRef = useRef<HTMLDivElement>(null);
  const shareMenuRef = useRef<HTMLDivElement>(null);

  // Close menus on outside click
  useEffect(() => {
    function handleClickOutside(e: MouseEvent) {
      if (menuRef.current && !menuRef.current.contains(e.target as Node)) {
        setMenuOpen(false);
      }
      if (shareMenuRef.current && !shareMenuRef.current.contains(e.target as Node)) {
        setShareMenuOpen(false);
      }
    }
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  // Live post data (likes/comments/caption/media/counters) is patched by the
  // Feed's single real-time listener, so no per-card post doc listener is
  // needed here - the card simply reconciles from its props.
  useEffect(() => {
    setLikesCount(post.likes || 0);
  }, [post.likes]);

  useEffect(() => {
    setReHiveCount(post.reHives || 0);
  }, [post.reHives]);

  useEffect(() => {
    return listenCommunityByPost(post.id, setCommunity);
  }, [post.id]);

  useEffect(() => {
    if (!user || !community) {
      setCommunityMember(null);
      return;
    }
    return listenCommunityMember(community.id, user.uid, setCommunityMember);
  }, [community, user]);

  // Check if current user has liked this post
  useEffect(() => {
    if (!user) {
      setLiked(false);
      return;
    }

    const likeRef = doc(db, "posts", post.id, "likes", user.uid);
    const unsubscribe = onSnapshot(likeRef, (snap) => {
      setLiked(snap.exists());
    });
    return () => unsubscribe();
  }, [post.id, user]);

  useEffect(() => {
    return listenToReHiveState(user?.uid, post.id, setReHived);
  }, [post.id, user?.uid]);

  useEffect(() => {
    return listenToSavedPostState(user?.uid, post.id, setSaved);
  }, [post.id, user?.uid]);

  // Live block state between the viewer and the post author (either direction).
  useEffect(() => {
    if (!user || !post.uid || user.uid === post.uid) {
      setBlockState("none");
      return;
    }
    return onSnapshot(doc(db, "blocks", blockIdFor(user.uid, post.uid)), (snap) => {
      if (!snap.exists()) {
        setBlockState("none");
        return;
      }
      const data = snap.data() as { blockerId?: string };
      setBlockState(data.blockerId === user.uid ? "blocked-by-me" : "blocked-them");
    });
  }, [post.id, user?.uid, post.uid]);

  async function handleLike() {
    if (!user || liking) return;

    setLiking(true);
    // Optimistic count bump - reconciled by the feed's real-time snapshot
    // (final Firestore state is always the source of truth).
    setLikesCount((count) => (liked ? Math.max(0, count - 1) : count + 1));

    const postRef = doc(db, "posts", post.id);
    const likeRef = doc(db, "posts", post.id, "likes", user.uid);

    try {
      // Atomic like/unlike: prevents double counting from double clicks or
      // simultaneous sessions (read + write in one transaction).
      let didLike = false;
      await runTransaction(db, async (tx) => {
        const likeSnap = await tx.get(likeRef);
        if (likeSnap.exists()) {
          tx.delete(likeRef);
          tx.update(postRef, { likes: increment(-1) });
          didLike = false;
        } else {
          tx.set(likeRef, {
            userId: user.uid,
            createdAt: new Date(),
          });
          tx.update(postRef, { likes: increment(1) });
          didLike = true;
        }
      });

      setLiked(didLike);

      if (didLike) {
        await recordPostEngagement({
          postId: post.id,
          actorId: user.uid,
          authorId: post.uid,
          type: "like",
          category: post.category,
        });
        await createNotification({
          recipientId: post.uid,
          actor: {
            uid: user.uid,
            username: myProfile?.username || "",
            displayName: myProfile?.displayName || user.displayName || "Hivez User",
            photoURL: myProfile?.photoURL || user.photoURL || "",
          },
          type: "like",
          text: post.caption || "your post",
          link: `/post/${post.id}`,
          postId: post.id,
        });
      }
    } catch (err) {
      console.error("Failed to update like:", err);
      // Reconcile back to the authoritative state.
      setLiked(liked);
      setLikesCount(post.likes || 0);
    } finally {
      setLiking(false);
    }
  }

  async function handleReHive() {
    if (!user) return;
    if (reHiving) return;
    setReHiving(true);
    setReHiveCount((count) => (reHived ? Math.max(0, count - 1) : count + 1));

    try {
      const result = await toggleReHive({
        userId: user.uid,
        post,
        actor: {
          uid: user.uid,
          username: myProfile?.username || "",
          displayName: myProfile?.displayName || user.displayName || "Hivez User",
          photoURL: myProfile?.photoURL || user.photoURL || "",
        },
      });
      setReHived(result.active);
      toast.success(result.active ? "ReHived" : "ReHive removed", { duration: 1400 });
    } catch (err) {
      console.error("Failed to update ReHive:", err);
      setReHiveCount(post.reHives || 0);
      toast.error(err instanceof Error ? err.message : "Could not update ReHive");
    } finally {
      setReHiving(false);
    }
  }

  async function handleVolunteer() {
    if (!user || volunteerBusy) return;
    setVolunteerBusy(true);
    try {
      let activeCommunity = community;
      if (!activeCommunity) {
        const owner = await getUserSummary(post.uid);
        const communityId = await createIssueCommunityForPost({
          postId: post.id,
          ownerId: post.uid,
          owner,
          caption: post.caption,
          category: post.category,
          location: post.location,
          locationSnapshot: post.locationSnapshot,
          mediaUrl: mediaItems[0]?.url || post.mediaUrl || "",
          mediaType: mediaItems[0]?.type || post.mediaType,
        });
        activeCommunity = {
          id: communityId,
          postId: post.id,
          issueId: post.id,
          title: post.caption || `${post.category || "Community"} issue`,
          description: post.caption || "Community issue",
          category: post.category || "community",
          location: post.location || null,
          locationSnapshot: post.locationSnapshot || null,
          mediaUrl: mediaItems[0]?.url || post.mediaUrl || "",
          mediaType: mediaItems[0]?.type || post.mediaType,
          ownerId: post.uid,
          owner,
          status: "REPORTED",
          memberCount: 1,
          activityCount: 0,
          rules: [],
          archived: false,
          createdAt: null,
          updatedAt: null,
        };
      }

      if (!communityMember && activeCommunity.ownerId !== user.uid) {
        await joinIssueCommunity(activeCommunity, await getUserSummary(user.uid));
        await recordPostEngagement({
          postId: post.id,
          actorId: user.uid,
          authorId: post.uid,
          type: "volunteer",
          category: post.category,
        });
      }
      navigate(`/issue-community/${activeCommunity.id}`);
    } catch (err) {
      console.error("Failed to open volunteer community:", err);
      toast.error("Could not open volunteer community");
    } finally {
      setVolunteerBusy(false);
    }
  }

  async function handleShare() {
    const url = `${window.location.origin}/post/${post.id}`;
    if (navigator.share) {
      await navigator.share({
        title: post.caption || "Check this post on Hivez",
        url,
      });
    } else {
      navigator.clipboard.writeText(url).then(() => {
        setCopied(true);
        setTimeout(() => setCopied(false), 2000);
      });
    }
    if (user) {
      await recordPostEngagement({ postId: post.id, actorId: user.uid, authorId: post.uid, type: "share", category: post.category });
    }
    setShareMenuOpen(false);
  }

  async function handleCopyLink() {
    const url = `${window.location.origin}/post/${post.id}`;
    await navigator.clipboard.writeText(url).then(() => {
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    });
    if (user) {
      await recordPostEngagement({ postId: post.id, actorId: user.uid, authorId: post.uid, type: "share", category: post.category });
    }
    setShareMenuOpen(false);
  }

  function handleCopyText() {
    if (post.caption) {
      navigator.clipboard.writeText(post.caption);
    }
    setMenuOpen(false);
  }

  async function deletePost() {
    if (!user || user.uid !== post.uid) return;
    setMenuOpen(false);

    const toastId = toast("Delete this post?", {
      description: "This action cannot be undone.",
      duration: 5000,
      position: "bottom-center",
      className: "bg-white dark:bg-zinc-900 border border-zinc-200 dark:border-zinc-800",
      action: {
        label: "Delete",
        onClick: async () => {
          try {
            await deleteDoc(doc(db, "posts", post.id));
            await updateDoc(doc(db, "users", user.uid), {
              posts: increment(-1),
            });
            toast.success("Post deleted", {
              duration: 2000,
              position: "bottom-center",
            });
          } catch (err) {
            console.error("Failed to delete post:", err);
            toast.error("Failed to delete post", {
              duration: 2000,
              position: "bottom-center",
            });
          }
        },
      },
      cancel: {
        label: "Cancel",
        onClick: () => toast.dismiss(toastId),
      },
    });
  }

  async function handleSave() {
    if (!user) {
      toast.error("Sign in to save posts");
      return;
    }
    if (saving) return;
    setSaving(true);
    try {
      const result = await toggleSavePost({ userId: user.uid, post });
      setSaved(result.saved);
      toast.success(result.saved ? "Post saved" : "Post removed from saved");
    } catch (err) {
      console.error("Failed to save post:", err);
      toast.error(err instanceof Error ? err.message : "Could not save this post");
    } finally {
      setSaving(false);
    }
  }

  async function handleBlock() {
    if (!user || !post.uid || blockBusy) return;
    setMenuOpen(false);
    setBlockBusy(true);
    try {
      if (blockState === "blocked-by-me") {
        await unblockUser(user.uid, post.uid);
        toast.success(`Unblocked @${post.username}`);
      } else {
        await blockUser(user.uid, post.uid);
        toast.success(`Blocked @${post.username}`);
      }
    } catch (err) {
      console.error("Failed to update block:", err);
      toast.error("Could not update block");
    } finally {
      setBlockBusy(false);
    }
  }

  async function handleReportPost() {
    if (!user) {
      toast.error("Sign in to report posts");
      return;
    }
    setMenuOpen(false);
    try {
      await createReport({
        reporterId: user.uid,
        reporterName: myProfile?.displayName || user.displayName || user.email || "Hivez User",
        targetId: post.id,
        targetType: "post",
        reason: "Reported from feed by user",
      });
      toast.success("Report submitted for review");
    } catch (err) {
      console.error("Failed to report post:", err);
      toast.error("Could not submit report");
    }
  }

  return (
    <>
      <article className="app-feed-card p-4 md:p-5">
        {/* Header: avatar, identity, more menu */}
        <div className="hv-post-header flex items-start justify-between gap-2">
          <div className="flex min-w-0 items-center gap-3">
            <img
              src={
                author.photoURL ||
                "https://ui-avatars.com/api/?name=Hivez&background=3d654c&color=fff"
              }
              alt={author.username}
              className="h-11 w-11 flex-shrink-0 rounded-full object-cover"
            />
            <div className="min-w-0 flex-1">
              <div className="hv-post-identity flex items-center gap-1.5 min-w-0">
                <button type="button" onClick={()=>navigate(`/profile?uid=${post.uid}`)} className="hv-post-name truncate text-[15px] font-bold text-zinc-900 hover:underline dark:text-white">
                  {author.displayName || author.username}
                </button>
                {author.verified && (
                  <BadgeCheck size={14} className="flex-shrink-0 text-sky-500" />
                )}
                <span className="hv-post-handle min-w-0 truncate text-[13px] text-zinc-500 dark:text-zinc-400">
                  @{author.username}
                </span>
                <span className="text-[13px] text-zinc-400 dark:text-zinc-500">·</span>
                <span className="hv-post-time flex-shrink-0 text-[13px] text-zinc-500 dark:text-zinc-400">
                  {timeAgo(post.createdAt)}
                </span>
              </div>
                {readableLocation && (
                  <button
                    type="button"
                    onClick={() => {
                      if (!postLocation) return;
                      navigate(`/map?post=${post.id}&lat=${postLocation.latitude}&lng=${postLocation.longitude}`);
                    }}
                    className="mt-0.5 inline-flex max-w-full items-center gap-1 text-xs text-zinc-500 transition hover:text-zinc-900 dark:text-zinc-400 dark:hover:text-white"
                  >
                    <MapPin size={12} className="flex-shrink-0" />
                    <span className="truncate">
                      {readableLocation}
                      {typeof post.distanceKm === "number" ? ` · ${formatDistance(post.distanceKm)}` : ""}
                    </span>
                  </button>
                )}
            </div>
          </div>

          {/* Three dot menu */}
          <div className="relative flex-shrink-0" ref={menuRef}>
                <button
                  aria-label="Post options"
                  aria-expanded={menuOpen}
                  onClick={() => {
                    setMenuOpen(!menuOpen);
                    setShareMenuOpen(false);
                  }}
                  className="-mr-1 flex-shrink-0 rounded-full p-2 transition hover:bg-zinc-100 dark:hover:bg-zinc-800"
                >
                  <MoreHorizontal size={20} className="text-zinc-500 dark:text-zinc-400" />
                </button>
                {menuOpen && (
                  <>
                    <div className="fixed inset-0 z-40" onClick={() => setMenuOpen(false)} />
                    <div className="app-popover-menu absolute right-0 top-full z-50 mt-1 w-48 rounded-xl border border-zinc-200 dark:border-zinc-800 bg-white dark:bg-zinc-900 py-1 shadow-xl">
                      <button
                        onClick={handleCopyText}
                        className="flex w-full items-center gap-3 px-4 py-2.5 text-sm text-zinc-700 dark:text-zinc-300 hover:bg-zinc-100 dark:hover:bg-zinc-800"
                      >
                        <Copy size={16} />
                        Copy text
                      </button>
                      <button
                        onClick={handleCopyLink}
                        className="flex w-full items-center gap-3 px-4 py-2.5 text-sm text-zinc-700 dark:text-zinc-300 hover:bg-zinc-100 dark:hover:bg-zinc-800"
                      >
                        <ExternalLink size={16} />
                        Copy link
                      </button>
                      {user && user.uid === post.uid && (
                        <>
                          <hr className="mx-3 border-zinc-200 dark:border-zinc-700" />
                          <button
                            onClick={deletePost}
                            className="flex w-full items-center gap-3 px-4 py-2.5 text-sm text-red-600 dark:text-red-400 hover:bg-red-50 dark:hover:bg-red-950/30"
                          >
                            <Trash2 size={16} />
                            Delete
                          </button>
                        </>
                      )}
                      <hr className="mx-3 border-zinc-200 dark:border-zinc-700" />
                      <button
                        onClick={() => void handleReportPost()}
                        className="flex w-full items-center gap-3 px-4 py-2.5 text-sm text-red-600 dark:text-red-400 hover:bg-red-50 dark:hover:bg-red-950/30"
                      >
                        <Flag size={16} />
                        Report
                      </button>
                      {user && post.uid && user.uid !== post.uid && (
                        <button
                          onClick={handleBlock}
                          disabled={blockBusy}
                          className="flex w-full items-center gap-3 px-4 py-2.5 text-sm text-red-600 disabled:opacity-50 dark:text-red-400 hover:bg-red-50 dark:hover:bg-red-950/30"
                        >
                          <Ban size={16} />
                          {blockState === "blocked-by-me" ? `Unblock @${post.username}` : `Block @${post.username}`}
                        </button>
                      )}
                      <button className="flex w-full items-center gap-3 px-4 py-2.5 text-sm text-zinc-700 dark:text-zinc-300 hover:bg-zinc-100 dark:hover:bg-zinc-800">
                        <UserMinus size={16} />
                        Mute
                      </button>
                    </div>
                  </>
                )}
              </div>
            </div>

            {/* Category chip */}
            {post.category && (
              <div className="mt-3">
                <span className="hv-post-category inline-flex items-center gap-2 rounded-full bg-[#f2c14e]/15 px-3.5 py-1.5 text-[11px] font-bold uppercase tracking-[0.08em] text-[#8a6d1f] dark:bg-[#f2c14e]/10 dark:text-[#f2c14e]">
                  <span className="h-1.5 w-1.5 rounded-full bg-amber-500 dark:bg-[#f2c14e]" />
                  {COMMUNITIES.find(hive=>hive.id === post.category)?.name || post.category.replaceAll("-", " ")}
                </span>
              </div>
            )}

            {/* Sensitive badge */}
            {post.sensitive && (
              <div className="mt-3">
                <span className="inline-flex items-center gap-1.5 rounded-full bg-zinc-200/80 px-3 py-1.5 text-[11px] font-bold text-zinc-600 dark:bg-zinc-800 dark:text-zinc-300">
                  <AlertTriangle size={13} />
                  Sensitive
                </span>
              </div>
            )}

            {/* Caption */}
            {post.caption && (
              <div className="mt-3">
                <p className="hv-post-caption whitespace-pre-wrap break-words text-[15px] leading-relaxed text-zinc-800 dark:text-zinc-200">
                  {post.caption}
                </p>
                {post.hashtags && post.hashtags.length > 0 && (
                  <div className="mt-1.5 flex flex-wrap gap-2">
                    {post.hashtags.map((tag, idx) => (
                      <button
                        key={idx}
                        className="text-sm text-sky-500 hover:underline"
                      >
                        {tag}
                      </button>
                    ))}
                  </div>
                )}
              </div>
            )}

            {/* Media */}
            {mediaItems.length > 0 && (
              <div className="mt-3 min-w-0 overflow-hidden">
                <MediaGrid items={mediaItems} sensitive={Boolean(post.sensitive)} />
              </div>
            )}

            {/* Actions */}
            <div className="mt-3 flex items-center justify-between border-t border-zinc-200/80 pt-1.5 dark:border-zinc-800/80">
              <div className="-ml-2 flex items-center gap-0.5 sm:gap-1">
              <button
                onClick={handleLike}
                aria-label={liked ? "Unlike post" : "Like post"}
                aria-pressed={liked}
                disabled={liking}
                className="flex items-center gap-1.5 rounded-full px-3 py-1.5 transition hover:bg-red-50 dark:hover:bg-red-950/30 group"
              >
                <motion.div
                  animate={liked && !reducedMotion ? { scale: [1, 1.3, 1] } : { scale: 1 }}
                  transition={{ duration: 0.3 }}
                >
                  <Heart
                    size={20}
                    className={
                      liked
                        ? "fill-red-500 text-red-500"
                        : "text-zinc-500 dark:text-zinc-400 group-hover:text-red-500"
                    }
                  />
                </motion.div>
                <span className={`text-[13px] font-medium ${liked ? "text-red-500" : "text-zinc-500 dark:text-zinc-400 group-hover:text-red-500"}`}>
                  {likesCount}
                </span>
              </button>
              <button
                onClick={() => (onCommentClick ? onCommentClick(post) : setCommentsOpen(true))}
                aria-label="Comments"
                className="flex items-center gap-1.5 rounded-full px-3 py-1.5 transition hover:bg-sky-50 dark:hover:bg-sky-950/30 group"
              >
                <MessageCircle size={20} className="text-zinc-500 dark:text-zinc-400 group-hover:text-sky-500" />
                <span className="text-[13px] font-medium text-zinc-500 dark:text-zinc-400 group-hover:text-sky-500">
                  {post.comments}
                </span>
              </button>
              <button
                type="button"
                onClick={handleReHive}
                disabled={!user || reHiving}
                className="flex items-center gap-1.5 rounded-full px-3 py-1.5 transition hover:bg-green-50 disabled:opacity-60 dark:hover:bg-green-950/30 group"
                aria-label={reHived ? "Remove ReHive" : "ReHive post"}
                aria-pressed={reHived}
              >
                <Repeat2 size={20} className={reHived ? "text-green-500" : "text-zinc-500 dark:text-zinc-400 group-hover:text-green-500"} />
                <span className={`text-[13px] font-medium ${reHived ? "text-green-500" : "text-zinc-500 dark:text-zinc-400 group-hover:text-green-500"}`}>
                  {reHiveCount}
                </span>
              </button>
              </div>

              <div className="-mr-2 flex items-center gap-0.5 sm:gap-1">
              <button
                onClick={handleVolunteer}
                disabled={volunteerBusy}
                className="flex items-center gap-1.5 rounded-full px-3 py-1.5 transition hover:bg-amber-50 disabled:opacity-60 dark:hover:bg-amber-950/30 group"
              >
                <HandHeart
                  size={18}
                  className={
                    communityMember || community?.ownerId === user?.uid
                      ? "fill-amber-500 text-amber-500"
                      : "text-zinc-500 dark:text-zinc-400 group-hover:text-amber-500"
                  }
                />
                <span className="sr-only">
                  {community?.ownerId === user?.uid ? "Manage" : communityMember ? "Joined" : "Volunteer"}
                </span>
              </button>

              {/* Save post */}
              <button
                type="button"
                onClick={handleSave}
                disabled={saving}
                aria-label={saved ? "Remove from saved posts" : "Save post"}
                aria-pressed={saved}
                className="flex items-center gap-1.5 rounded-full px-3 py-1.5 transition hover:bg-amber-50 disabled:opacity-60 dark:hover:bg-amber-950/30 group"
              >
                <Bookmark
                  size={18}
                  className={saved ? "fill-amber-500 text-amber-500" : "text-zinc-500 dark:text-zinc-400 group-hover:text-amber-500"}
                />
              </button>

              {/* Share button with dropdown */}
              <div className="relative" ref={shareMenuRef}>
                <button
                  onClick={() => {
                    setShareMenuOpen(!shareMenuOpen);
                    setMenuOpen(false);
                  }}
                  className="flex items-center gap-1.5 rounded-full px-3 py-1.5 transition hover:bg-blue-50 dark:hover:bg-blue-950/30 group"
                  aria-label="Share post"
                >
                  {copied ? (
                    <span className="text-xs text-green-500 font-medium">Copied!</span>
                  ) : (
                    <Share2 size={20} className="text-zinc-500 dark:text-zinc-400 group-hover:text-blue-500" />
                  )}
                </button>
                {shareMenuOpen && (
                  <>
                    <div className="fixed inset-0 z-40" onClick={() => setShareMenuOpen(false)} />
                    <div className="app-popover-menu absolute left-0 top-full z-50 mt-1 w-48 rounded-xl border border-zinc-200 dark:border-zinc-800 bg-white dark:bg-zinc-900 py-1 shadow-xl">
                      <button
                        onClick={handleShare}
                        className="flex w-full items-center gap-3 px-4 py-2.5 text-sm text-zinc-700 dark:text-zinc-300 hover:bg-zinc-100 dark:hover:bg-zinc-800"
                      >
                        <Share2 size={16} />
                        Share
                      </button>
                      <button
                        onClick={handleCopyLink}
                        className="flex w-full items-center gap-3 px-4 py-2.5 text-sm text-zinc-700 dark:text-zinc-300 hover:bg-zinc-100 dark:hover:bg-zinc-800"
                      >
                        <Copy size={16} />
                        Copy link
                      </button>
                    </div>
                  </>
                )}
              </div>
              <button
                type="button"
                onClick={() => (user ? setSendSheetOpen(true) : toast.error("Sign in to send posts"))}
                className="flex items-center gap-1.5 rounded-full px-3 py-1.5 transition hover:bg-blue-50 dark:hover:bg-blue-950/30 group"
                aria-label="Send post via direct message"
              >
                <Send size={20} className="text-zinc-500 dark:text-zinc-400 group-hover:text-blue-500" />
              </button>
              </div>
            </div>
      </article>

      <CommentsSheet
        post={post}
        open={commentsOpen}
        onClose={() => setCommentsOpen(false)}
      />
      <PostSendSheet post={post} open={sendSheetOpen} onClose={() => setSendSheetOpen(false)} />
    </>
  );
}

import { NavLink } from "react-router-dom";
import { Bell, Bookmark, HandHeart, Home, Map, MessageCircle, Search, Settings, User, LogOut, ArrowUpRight, ChevronRight, type LucideIcon } from "lucide-react";
import { COMMUNITIES } from "@/constants/communities";
import HiveSearch from "@/components/hiveSearch/HiveSearch";

export const workspaceLinks: { to: string; label: string; icon: LucideIcon }[] = [
  { to: "/", label: "Your feed", icon: Home },
  { to: "/search", label: "Explore", icon: Search },
  { to: "/volunteering", label: "Lend a hand", icon: HandHeart },
  { to: "/map", label: "Neighbourhood map", icon: Map },
  { to: "/chats", label: "Messages", icon: MessageCircle },
  { to: "/notifications", label: "Notifications", icon: Bell },
  { to: "/saved", label: "Saved posts", icon: Bookmark },
  { to: "/profile", label: "Your profile", icon: User },
];

export default function HiveNav({ collapsed, unread, onNavigate, onClose, onLogout, onCreate }: {
  collapsed: boolean; unread: number; onNavigate: (path: string) => void; onClose: () => void; onLogout: () => void; onCreate: () => void;
}) {
  return <div className={`hv-navigation ${collapsed ? "is-compact" : ""}`}>
    <nav aria-label="Main navigation" className="hv-nav-links">
      {!collapsed && <p className="hv-rail-label">YOUR NEIGHBOURHOOD</p>}
      {workspaceLinks.map(({to,label,icon:Icon}) => <NavLink key={to} to={to} end={to === "/" || to === "/profile"} title={collapsed ? label : undefined} aria-label={label} onClick={onClose} className={({isActive})=>`hv-nav-link ${isActive ? "is-active" : ""}`}>
        <Icon size={19} strokeWidth={1.65} aria-hidden="true" /><span>{label}</span>
        {to === "/notifications" && unread > 0 && <b className="hv-count">{unread > 99 ? "99+" : unread}</b>}
      </NavLink>)}
    </nav>
    {!collapsed && <div className="hv-rail-hives">
      <div className="hv-rail-section-title"><p className="hv-rail-label">FIND YOUR HIVE</p><ArrowUpRight size={14} aria-hidden="true" /></div>
      <HiveSearch onSelect={id=>onNavigate(`/hive/${id}`)} placeholder="Find a hive" maxResults={4} showSuggestions={false} />
      <div className="hv-hive-links">{COMMUNITIES.slice(0,3).map((hive,i)=><NavLink to={`/hive/${hive.id}`} onClick={onClose} key={hive.id}><span className={`hv-hive-dot hv-hive-dot--${i}`} aria-hidden="true" /><span>{hive.name}</span><ChevronRight size={13} aria-hidden="true" /></NavLink>)}</div>
      <button className="hv-rail-invite" onClick={onCreate}><span>Notice something?<br/><strong>Start a conversation.</strong></span><ArrowUpRight size={18} aria-hidden="true" /></button>
    </div>}
    <div className="hv-nav-bottom">
      <NavLink to="/settings" onClick={onClose} title={collapsed ? "Settings" : undefined} aria-label="Settings" className="hv-nav-link"><Settings size={19} strokeWidth={1.65} aria-hidden="true" /><span>Settings</span></NavLink>
      <button onClick={onLogout} className="hv-nav-link hv-logout" title={collapsed ? "Log out" : undefined} aria-label="Log out"><LogOut size={19} strokeWidth={1.65} aria-hidden="true" /><span>Log out</span></button>
      {!collapsed && <p className="hv-rail-signoff">A little local. A lot possible.</p>}
    </div>
  </div>;
}

